#include <bits/stdc++.h>
using namespace std;

using int64 = long long;
using i128 = __int128_t;

int64 solve(int64 n) {
    int64 ans = 0;

    for (int64 level = 1;; ++level) {
        i128 lvl = level;
        i128 first = lvl * (3 * lvl + 1) / 2;

        if (first > n) break;

        if ((static_cast<i128>(n) - first) % (3 * lvl) == 0) {
            ++ans;
        }
    }

    return ans;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    vector<int64> input;
    int64 value;

    while (cin >> value) {
        input.push_back(value);
    }

    if (input.size() > 1 && input[0] == static_cast<int64>(input.size() - 1)) {
        for (size_t i = 1; i < input.size(); ++i) {
            cout << solve(input[i]) << '\n';
        }
    } else {
        for (int64 n : input) {
            cout << solve(n) << '\n';
        }
    }

    return 0;
}

